-- Phase 10I server contract assertions. Each call raises immediately on a
-- failed invariant and emits one stable PASS line for the verifier.
create or replace function phase10i_test.ok(condition boolean,label text)
returns void language plpgsql as $$
begin
  if not coalesce(condition,false) then raise exception 'FAIL %',label; end if;
  raise notice 'PASS %',label;
end;
$$;

