select phase10i_test.ok((select qual like '%manager%' from pg_policies where tablename='routine_client_instances'),'136 manager sees own-org instances');
select phase10i_test.ok(exists(select 1 from pg_policies where tablename='routine_client_instances' and policyname='routine_client_instances_select' and qual is not null),'137 user sees own instances');
select phase10i_test.ok(exists(select 1 from pg_policies where tablename='routine_offline_operation_receipts' and policyname='routine_offline_receipts_select' and qual is not null),'138 user sees own receipts');
select phase10i_test.ok((select qual like '%routine_run_is_visible%' from pg_policies where tablename='routine_delivery_reconciliations'),'139 participant reconciliation visibility');
select phase10i_test.ok((select qual not like '% true%' from pg_policies where tablename='routine_delivery_reconciliations'),'140 no broad staff reconciliation');
select phase10i_test.ok(not exists(select 1 from pg_policies where tablename in('routine_client_instances','routine_offline_operation_receipts','routine_delivery_reconciliations') and (qual='true' or with_check='true')),'141 cross-org RLS bounded');
select phase10i_test.ok(pg_get_functiondef('public.routine_phase10i_assert_instance(uuid,jsonb)'::regprocedure) like '%organizationId%','142 cross-org RPC bounded');
select phase10i_test.ok((select qual not like '%counter%' from pg_policies where tablename='routine_client_instances'),'143 counter gets no access');
select phase10i_test.ok((select bool_and(qual like '%current_user_is_shared_device%') from pg_policies where tablename in('routine_client_instances','routine_offline_operation_receipts','routine_delivery_reconciliations')),'144 shared device blocked');
select phase10i_test.ok((select bool_and(qual like '%routine_current_user_is_active%') from pg_policies where tablename in('routine_client_instances','routine_offline_operation_receipts','routine_delivery_reconciliations')),'145 inactive user blocked');
select phase10i_test.ok((select bool_and(qual like '%organization_id = routine_current_user_organization_id%' or qual like '%organization_id = public.routine_current_user_organization_id%') from pg_policies where tablename in('routine_client_instances','routine_offline_operation_receipts','routine_delivery_reconciliations')),'146 org-less user blocked');
select phase10i_test.ok(not has_table_privilege('anon','public.routine_client_instances','SELECT'),'147 anon has no access');
select phase10i_test.ok(not has_table_privilege('authenticated','public.routine_offline_operation_receipts','INSERT') and not has_table_privilege('authenticated','public.routine_delivery_reconciliations','UPDATE'),'148 direct DML blocked');
